                f.write(f"v {s['f0']:.6f} {s['f1']:.6f} {s['f2']:.6f}\n")
                f.write(f"# sphere {i}: radius={s['f3']:.2f}, ({s['s0']},{s['s1']},{s['s2']},{s['s3']})\n")
